<style>.em-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.em-card{border:1px solid #e5e7eb;border-radius:8px;padding:16px;background:#fff}.em-card h2{margin:6px 0 0}.em-muted{color:#6b7280;font-size:12px}</style>
<div class="page-title clearfix"><h1>Email Marketing Dashboard</h1><div class="title-button-group"><a class="btn btn-primary" href="<?php echo site_url('email_marketing/create'); ?>">Create campaign</a> <a class="btn btn-default" href="<?php echo site_url('email_marketing/contacts'); ?>">Contacts</a> <a class="btn btn-default" href="<?php echo site_url('email_marketing/reports'); ?>">Reports</a></div></div>
<div class="em-grid"><?php foreach(['opted_in'=>'Opted-in contacts','suppressed'=>'Suppressed','draft'=>'Draft campaigns','scheduled'=>'Scheduled','completed'=>'Completed','sent'=>'Sent','failed'=>'Failed','skipped'=>'Skipped','unsubscribed'=>'Unsubscribed'] as $key=>$label): ?><div class="em-card"><div class="em-muted"><?php echo esc($label); ?></div><h2><?php echo (int)($totals[$key]??0); ?></h2></div><?php endforeach; ?><div class="em-card"><div class="em-muted">Open rate</div><h2>N/A</h2><small>No tracking configured</small></div><div class="em-card"><div class="em-muted">Click rate</div><h2>N/A</h2><small>No tracking configured</small></div><div class="em-card"><div class="em-muted">Bounce rate</div><h2>N/A</h2><small>No provider events</small></div></div>
<div class="row mt20"><div class="col-md-7"><div class="card"><div class="card-header"><h4>Recent campaign activity</h4></div><table class="table"><thead><tr><th>Campaign</th><th>Recipient</th><th>Status</th><th>Time</th></tr></thead><tbody><?php foreach($activity as $row): ?><tr><td><?php echo esc($row->campaign_name); ?></td><td><?php echo esc($row->email); ?></td><td><?php echo esc($row->status); ?></td><td><?php echo esc($row->sent_at?:$row->queued_at); ?></td></tr><?php endforeach; if(!$activity): ?><tr><td colspan="4">No delivery activity.</td></tr><?php endif; ?></tbody></table></div></div><div class="col-md-5"><div class="card"><div class="card-header"><h4>Recent delivery failures</h4></div><table class="table"><thead><tr><th>Campaign</th><th>Recipient</th><th>Error</th></tr></thead><tbody><?php foreach($failures as $row): ?><tr><td><?php echo esc($row->campaign_name); ?></td><td><?php echo esc($row->email); ?></td><td><?php echo esc($row->error_details?:'Mail transport failed'); ?></td></tr><?php endforeach; if(!$failures): ?><tr><td colspan="3">No failures.</td></tr><?php endif; ?></tbody></table></div></div></div>
